#include <bits/stdc++.h>
using namespace std;

long long choose(int n, int k, const std::vector<long long>& fact, long long mod) {
    long long denom = (fact[k] * fact[n - k]) % mod;
    long long denomInv = pow_mod(denom, mod - 2, mod);
    return (fact[n] * denomInv) % mod;
}

long long pow_mod(long long base, int exp, long long mod) {
    long long res = 1LL;
    base %= mod;
    while (exp > 0) {
        if (exp & 1)
            res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N;
    long long K;
    cin >> N >> K;

    const long long MOD = 998244353LL;

    if (K >= N) {
        cout << 0 << "\n";
        return 0;
    }
    int C = (int)(N - K);

    std::vector<long long> factorials(200001);
    factorials[0] = 1;
    for (int i = 1; i <= 200000; i++) {
        factorials[i] = (factorials[i - 1] * i) % MOD;
    }

    long long total = 0;
    int sign = 1;
    for (int i = C; i > 0; i--) {
        long long val = (choose(C, i, factorials, MOD) * pow_mod(i, N, MOD)) % MOD;
        total = (total + sign * val + 2 * MOD) % MOD;
        sign *= -1;
    }

    long long multiplier = 2 * choose(N, C, factorials, MOD);
    if (C == N)
        multiplier = 1LL;
    cout << (total * multiplier) % MOD << "\n";

    return 0;
}
